def updated_school_records(base_text: str = LAST_YEAR_SCHOOL_RECORDS) -> str:
    """按虚构更新示例更新纪录表，保留原有行序。"""
    lines = []
    for line in base_text.splitlines():
        cells = line.split("\t")
        if len(cells) == 5 and (cells[0], cells[1]) in TENTH_MEET_RECORD_UPDATES:
            cells[2], cells[3] = TENTH_MEET_RECORD_UPDATES[(cells[0], cells[1])]
            cells[4] = "第十届校运会"
            line = "\t".join(cells)
        lines.append(line)
    return "\n".join(lines)


LATEST_SCHOOL_RECORDS = updated_school_records()


